/* Dashboard tokens: dense odds/data surfaces; brand palette stays in darkhorse-brand.css. */
body.gameday{--bg:#080c12;--ink:#f2f6f8;--line:#29353f;--mint:#80f7da;--gold:#f9d88c;--muted:#a9b9b3;background:var(--bg);color:var(--ink)}
.gd-header-actions{display:flex;gap:8px}.gd-header-actions b,.gd-slip-dock b{padding:3px 7px;background:var(--mint);color:var(--bg);border-radius:4px;margin-left:5px}.gd-header-actions button{font-size:12px}.gameday #mainNavigation{position:sticky;top:0;z-index:40;display:flex;gap:4px;margin:0 -1px 24px;padding:6px 0;background:var(--bg);border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:visible}.gameday #mainNavigation>button,.gameday #mainNavigation summary{font-size:14px;font-weight:600;border:0;border-radius:6px;padding:12px 20px;color:var(--muted);background:none;white-space:nowrap}.gameday #mainNavigation .active{color:var(--mint);box-shadow:inset 0 -3px var(--mint)}#gdMore{position:relative;padding:0;margin:0 0 0 auto;border:0}#gdMore summary{list-style:none}#gdMore summary:after{content:' ⌄'}.gd-more-menu{position:absolute;right:0;top:100%;width:220px;background:var(--bg);padding:8px;border:1px solid var(--line);box-shadow:0 12px 40px #080c12}.gd-more-menu button{display:block;width:100%;text-align:left;border:0}.gameday #slate>article,.gameday #slate>#seabiscuitHub,.refresh-banner:not(.stale){display:none}.refresh-banner.stale{font-size:12px;padding:10px;border:1px solid var(--gold);color:var(--gold);margin:8px 0}.gd-ticker{height:104px;max-width:1320px;display:flex;gap:12px;align-items:center;margin:auto;padding:0 24px 12px}.gd-ticker-label{flex:0 0 105px}.gd-ticker-label b{font-size:12px;letter-spacing:.1em}.gd-ticker-label small{display:none}.gd-ticker>button{width:44px;flex-shrink:0}.gd-ticker-rail{display:flex;gap:8px;overflow:auto;min-width:0;scrollbar-width:thin;flex:1}.gd-tick{flex:0 0 180px;font-size:12px;text-align:left;padding:8px 10px;display:grid;gap:3px}.gd-tick-top{display:flex;justify-content:space-between;color:var(--mint)}.gd-tick-top em{font-style:normal;color:var(--muted)}.gd-tick-team{display:flex;align-items:center;gap:6px}.gd-tick-team img{width:18px;height:18px;object-fit:contain}.gd-tick-team strong{margin-left:auto}.gd-tick>small{display:none}.gd-score-empty{font-size:12px;color:var(--muted);padding:12px 0}.gd-feature-heading{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:18px}.gd-feature-heading h1{font:32px/1.2 var(--brand-display);letter-spacing:.015em;margin:6px 0 0}.gd-feature-heading>span{font-size:12px;color:var(--muted)}.gd-feature-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:16px}.gd-feature-card{margin:0;padding:20px;background:linear-gradient(135deg,#80f7da0c,transparent);border-top:3px solid var(--mint)}.gd-special{border-color:var(--gold);background:linear-gradient(135deg,#f9d88c12,transparent)}.gd-special .gd-card-head b{color:var(--gold)}.gd-feature-teams{display:flex;align-items:center;gap:12px;margin:18px 0}.gd-feature-teams>div{min-width:0;flex:1}.gd-feature-teams h2{font-size:20px;margin:0 0 4px}.gd-feature-teams span{font-size:12px;color:var(--muted)}.gd-feature-teams img{width:46px;height:46px}.gd-feature-odds{font-size:26px;font-weight:700;color:var(--mint);padding:8px 12px;white-space:nowrap}.gd-special .gd-feature-odds{color:var(--gold)}.gd-feature-odds small{display:block;font-size:12px;font-weight:400}.gd-feature-stats{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.gd-feature-stats small{display:block;font-size:12px}.gd-feature-stats strong{font-size:25px;line-height:1.4}.gd-feature-card .sb-reason{display:block;min-height:68px;font-size:13px;line-height:1.55;margin:14px 0}.gd-feature-card .sb-source{display:block;font-size:12px;color:var(--muted);margin:10px 0 0}.sb-kickoff,.sb-reason,.sb-source{display:block}.gd-feature-empty{min-height:210px;margin:0;border-top:3px solid var(--gold);background:linear-gradient(120deg,#f9d88c0c,transparent);padding:24px}.gd-feature-empty h2{font:28px/1.2 var(--brand-display);margin:12px 0}.gd-feature-empty p{max-width:620px;color:var(--muted)}.gd-feature-empty>div{display:flex;gap:8px;flex-wrap:wrap}.gd-board-head{display:flex;justify-content:space-between;margin:36px 0 16px}.gd-board-head h2{font:23px var(--brand-display);margin:0}.gd-board-head span{color:var(--mint)}.gd-calendar{display:flex;gap:8px;margin:12px 0 16px}.gd-calendar>button{flex:0 0 44px}.gd-date-rail{display:flex;gap:6px;overflow:auto;flex:1;min-width:0;scroll-snap-type:x mandatory;scrollbar-width:thin;padding-bottom:6px}.gd-day{flex:0 0 84px;scroll-snap-align:start;padding:8px;display:flex;flex-direction:column;align-items:center;gap:2px}.gd-day small,.gd-day span{font-size:12px}.gd-day b{font-size:22px}.gd-day.selected{border-color:var(--mint);background:#80f7da12;color:var(--mint)}.gd-filters{display:grid;grid-template-columns:1fr 1.5fr 1fr 1fr;gap:12px;margin-bottom:20px}.gd-filters select,.gd-filters input{font-size:14px}.gd-grid-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:18px 0 8px}.gd-grid-head h2{font-size:18px;margin:0}.gd-grid-head>span,.gd-muted{font-size:12px;color:var(--muted)}.gd-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.gd-card{padding:18px;margin:0;background:linear-gradient(145deg,#80f7da06,transparent);min-width:0}.gd-card-head{display:flex;justify-content:space-between;gap:8px;font-size:12px;color:var(--muted)}.gd-card-head span:last-child{max-width:45%;text-align:right}.gd-card-head b{color:var(--mint)}.gd-matchup-teams{display:flex;gap:8px;align-items:center;margin:18px 0}.gd-matchup-teams>div{display:flex;gap:8px;align-items:center;flex:1;min-width:0}.gd-matchup-teams .ranked-name{font-size:14px;font-weight:600}.gd-matchup-teams .teamlogo{width:30px;height:30px}.gd-matchup-teams small,.gd-at{font-size:12px;color:var(--muted)}.gd-moneyline-pick{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;background:#80f7da0b;border:1px solid var(--line);border-radius:8px}.gd-moneyline-pick small{color:var(--mint);font-size:12px}.gd-moneyline-pick h3{font:600 16px/1.4 Inter,sans-serif;margin:4px 0}.gd-moneyline-pick span{font-size:12px;color:var(--muted)}.gd-price{font-size:16px;font-weight:600;min-width:68px}.gd-picked{border-color:var(--mint);color:var(--mint);background:#80f7da0c}.gd-price small{display:block;font-size:12px;font-weight:400}.gd-price.gd-in-ticket{box-shadow:inset 0 0 0 2px var(--mint)}.gd-price.gd-in-ticket:after{content:' ✓'}.gd-no-price{max-width:90px;text-align:right}.gd-projection{padding:14px 0 8px;margin:0;font-size:14px;font-weight:600}.gd-picks-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.gd-picks-row small{display:block;font-size:12px;color:var(--muted)}.gd-picks-row b{display:block;font-size:14px;margin-top:4px}.gd-card-why{font-size:13px;margin:12px 0}.gd-source{display:block;font-size:12px;color:var(--muted)}.gd-card-footer{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:12px;font-size:12px}.gd-card-footer button,.gd-card-footer a{font-size:12px;min-height:44px;padding:12px 8px}.gd-card-footer a{display:inline-flex;align-items:center}.gd-all-markets{font-size:12px;margin:12px 0}.gd-all-markets summary{font-size:12px}.gd-match-moneylines,.gd-market-board{display:grid;grid-template-columns:1fr 1fr;gap:8px}.gd-market-price{display:flex;flex-direction:column;gap:4px;width:100%;margin:6px 0;font-size:13px}.gd-market-price span{font-weight:400}.gd-empty{grid-column:1/-1;padding:24px;border:1px dashed var(--line);border-radius:10px;color:var(--muted)}.gd-empty button{margin:4px}.gd-warning{font-size:12px;color:var(--gold);margin-top:10px}.gd-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.gd-panel-head h2{margin:0}.gd-live-team{display:grid;grid-template-columns:34px 1fr auto;gap:12px;align-items:center;padding:12px 0}.gd-live-team img{width:30px;height:30px;object-fit:contain}.gd-live-team>b{font-size:25px}.gd-live-team strong{font-size:16px}.gd-slip-dock{position:sticky;bottom:0;z-index:45;display:flex;width:100%;justify-content:space-between;align-items:center;gap:12px;padding:12px 24px;border-radius:0;background:var(--bg);color:var(--mint);border:0;border-top:1px solid var(--mint);min-height:60px}.gd-slip-dock strong{font-size:12px}.gd-slip-backdrop{position:fixed;inset:0;background:#080c12cc;z-index:90}.gd-slip{position:fixed;right:0;top:0;bottom:0;width:min(460px,100%);background:var(--bg);border-left:1px solid var(--line);z-index:100;overflow:auto;padding:20px;padding-bottom:calc(24px + env(safe-area-inset-bottom))}.gd-slip-heading{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:14px}.gd-slip-heading button{font-size:24px;width:44px}.gd-slip-open{overflow:hidden}.gd-slip .gd-builder{border:0;padding:16px 0;margin:0}.gd-slip .gd-panel-head{flex-wrap:wrap}.gd-build-auto{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:16px 0}.gd-build-auto>div{width:100%}.gd-build-auto small{display:block}.gd-build-auto select{width:100px}.gd-build-auto button{flex:1;font-size:12px}.gd-ticket-math{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.gd-ticket-math strong{display:block;font-size:22px}.gd-ticket-math small{font-size:12px}.gd-ticket-actions{display:flex;gap:8px;flex-wrap:wrap}.gd-primary{background:var(--mint);color:var(--bg);font-weight:600}.gd-primary:hover{color:var(--bg)}.gd-leg{display:flex;gap:10px;padding:14px 0;border-bottom:1px solid var(--line);align-items:center}.gd-leg>div{flex:1;min-width:0}.gd-leg strong{font-size:14px}.gd-leg small{display:block;font-size:12px}.gd-leg button{flex-shrink:0;width:44px}.gd-tracker-stats{display:flex;flex-wrap:wrap;gap:20px;margin:20px 0}.gd-tracker-stats b{display:block;font-size:24px}.gd-tracker-stats small{display:block}.gd-tracked summary{display:flex;gap:12px;flex-wrap:wrap}.gd-tracked p{display:flex;justify-content:space-between;gap:12px}.gd-result-win{color:var(--mint)}.gd-result-loss,.gd-result-pending{color:var(--gold)}.gd-toast{position:fixed;bottom:75px;left:50%;transform:translateX(-50%);width:min(520px,calc(100% - 32px));z-index:110;background:var(--bg);border:1px solid var(--mint);padding:12px;display:flex;align-items:center;gap:12px;box-shadow:0 8px 30px #080c12;font-size:13px}.gd-toast button{font-size:12px;flex-shrink:0}.gd-lens{margin:20px 0;padding:20px;border:1px solid var(--mint);border-radius:12px}.gd-lens-layout{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:24px}.gd-orbit{position:relative;max-width:280px;margin:auto}.gd-orbit svg{width:100%;display:block}.gd-orbit-grid{fill:none;stroke:var(--line);stroke-width:1}.gd-orbit-base{fill:none;stroke:var(--line);stroke-width:8}#gdOrbitArc{fill:none;stroke:var(--mint);stroke-width:8}.gd-orbit-core{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center}.gd-orbit-core strong{font:44px var(--brand-display)}.gd-orbit-core span,.gd-orbit-core small{font-size:12px}.gd-lens-teams{display:flex;align-items:center;justify-content:center;gap:12px}.gd-lens-teams b{font-size:28px}.gd-slider-labels{display:flex;justify-content:space-between;font-size:12px}.gd-lens h3{font-size:16px;margin-top:16px}.gd-report-detail{margin:12px 0}.gameday #loading{padding:20px}.gameday #rankingLegend{font-size:12px}.gameday .ranking-badge,.gameday .ranking-current-label,.gameday .ranking-historical-label{font-size:12px}.gameday .sb-card{min-width:0}.gameday .sb-card .sb-reason,.gameday .sb-card .sb-kickoff,.gameday .sb-card .sb-source{display:block;font-size:12px}.gameday .sb-rail{max-width:100%}
@media(max-width:1100px){.gd-feature-grid{grid-template-columns:1fr 1fr}.gd-feature-card:first-child{grid-column:1/-1}.gd-feature-card:first-child .sb-reason{min-height:0}.gd-grid{grid-template-columns:1fr 1fr}}
@media(max-width:760px){.gd-header-actions button:first-child{display:none}.gd-header-actions button{padding:8px}.gameday #mainNavigation{margin-bottom:18px;gap:0}.gameday #mainNavigation>button,.gameday #mainNavigation summary{font-size:13px;padding:12px 13px;min-height:46px}.gd-ticker{padding:0 16px 8px;gap:8px}.gd-ticker>button{display:none}.gd-ticker-label{flex-basis:72px}.gd-tick{flex-basis:160px}.gd-feature-heading{display:block;margin:12px 0}.gd-feature-heading h1{font-size:28px}.gd-feature-heading>span{display:block;margin-top:5px}.gd-feature-grid{display:flex;flex-direction:column}.gd-feature-card{padding:16px}.gd-feature-card .sb-reason{min-height:0}.gd-feature-empty{padding:18px;min-height:230px}.gd-feature-empty h2{font-size:25px}.gd-feature-empty p{font-size:13px}.gd-feature-empty>div button{font-size:12px}.gd-feature-teams{margin:12px 0}.gd-feature-stats{padding:10px 0}.gd-feature-stats strong{font-size:24px}.gd-board-head{margin-top:28px}.gd-calendar>button{display:none}.gd-filters{grid-template-columns:1fr 1fr;gap:10px}.gd-filters input,.gd-filters select{font-size:16px}.gd-grid{grid-template-columns:1fr}.gd-grid-head h2{font-size:17px}.gd-card{padding:16px}.gd-slip-dock{padding:12px 16px}.gd-slip{padding:16px}.gd-lens-layout{grid-template-columns:1fr}.gd-orbit{width:200px}.gd-panel-head{flex-wrap:wrap}.gd-feature-card .gd-card-footer small{max-width:95px;text-align:right}.gameday .gd-market-price{min-width:0}.gd-matchup-teams .ranked-name{font-size:15px}.gd-card-footer>span{font-size:12px}.gd-more-menu{width:200px}}

.boot main{visibility:hidden;min-height:900px}.boot:after{content:"Loading model picks…";position:absolute;top:140px;left:24px;color:var(--muted);font-size:14px}.boot .darkhorse-header{min-height:90px}

/* Compact game cards: matchup, rankings, broadcast, then three model picks. */
.gd-pick-card { padding: 20px 18px 8px; background: #0c121a; border: 1px solid var(--line); border-radius: 12px; }
.gd-pick-card.gd-feature-card { padding: 20px 18px 8px; border-top: 1px solid var(--gold); }
.gd-pick-tag { margin-bottom: 18px; color: var(--gold); font-size: 11px; font-weight: 600; letter-spacing: .1em; }
.gd-saved-tag { color: var(--muted); letter-spacing: .025em; }
.gd-school-matchup { display: grid; grid-template-columns: minmax(0,1fr) 26px minmax(0,1fr); gap: 8px; align-items: start; }
.gd-school { min-width: 0; display: flex; flex-direction: column; align-items: center; text-align: center; }
.gd-school > .teamlogo { display: block; width: 64px; height: 64px; object-fit: contain; margin: 0 0 12px; }
.gd-logo-fallback { width: 64px; height: 64px; display: grid; place-items: center; margin-bottom: 12px; font-size: 20px; font-weight: 600; }
.gd-school h3 { display: flex; align-items: center; justify-content: center; min-height: 40px; max-width: 100%; margin: 0 0 10px; font: 17px/1.15 var(--brand-display); letter-spacing: .03em; overflow-wrap: anywhere; }
.gd-versus { margin-top: 25px; text-align: center; color: #8b9ca9; font-size: 11px; font-weight: 600; letter-spacing: .08em; }
.gd-school-ranks { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); width: 100%; max-width: 160px; }
.gd-school-ranks > span { display: flex; flex-direction: column; align-items: center; gap: 3px; border-right: 1px solid var(--line); }
.gd-school-ranks > span:last-child { border-right: 0; }
.gd-school-ranks small { font-size: 10px; color: #a9b9c4; line-height: 1.25; letter-spacing: .05em; }
.gd-school-ranks b { font: 600 13px/1.3 Inter,sans-serif; color: var(--ink); font-variant-numeric: tabular-nums; }
.gd-school-ranks sup { color: var(--gold); font-size: 10px; }
.gd-game-info { margin: 20px 0 17px; text-align: center; }
.gd-game-info p { margin: 0; font-size: 13px; line-height: 1.5; }
.gd-game-info time { font-weight: 600; white-space: nowrap; }
.gd-game-info .gd-game-location { margin-top: 5px; font-size: 12px; color: var(--muted); }
.gd-pick-strip { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 0; border-radius: 7px; }
.gd-pick-cell { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 7px; width: 100%; min-width: 0; min-height: 72px; padding: 10px 5px; margin: 0; border: 1px solid color-mix(in srgb,var(--pick-color) 78%,#fff 22%); border-radius: 0; color: var(--ink); background: linear-gradient(115deg,color-mix(in srgb,var(--pick-color) 19%,#0c121a),color-mix(in srgb,var(--pick-second) 14%,#0c121a)); box-shadow: inset 0 0 14px color-mix(in srgb,var(--pick-color) 8%,transparent),0 0 9px color-mix(in srgb,var(--pick-color) 12%,transparent); }
.gd-pick-cell:first-child { border-radius: 7px 0 0 7px; }
.gd-pick-cell + .gd-pick-cell { margin-left: -1px; width: calc(100% + 1px); }
.gd-pick-cell:last-child { border-radius: 0 7px 7px 0; }
.gd-pick-cell > small { font: 500 9px/1.2 Inter,sans-serif; letter-spacing: .09em; color: #c6d2da; }
.gd-pick-value { display: flex; align-items: center; justify-content: center; gap: 6px; min-width: 0; }
.gd-pick-value .teamlogo { display: block; width: 25px; height: 25px; object-fit: contain; margin: 0; }
.gd-pick-value b { font: 600 20px/1.25 Inter,sans-serif; font-variant-numeric: tabular-nums; letter-spacing: -.035em; white-space: nowrap; }
.gd-pick-cell:disabled { opacity: 1; cursor: default; }
.gd-pick-cell.gd-pick-empty { border-color: var(--line); background: #101820; box-shadow: none; }
.gd-pick-cell:not(:disabled):hover { z-index: 1; background: linear-gradient(115deg,color-mix(in srgb,var(--pick-color) 30%,#0c121a),color-mix(in srgb,var(--pick-second) 22%,#0c121a)); border-color: color-mix(in srgb,var(--pick-color) 50%,#fff); color: #fff; }
.gd-pick-cell.gd-in-ticket { z-index: 1; box-shadow: inset 0 0 0 1px #f2f6f8,0 0 14px color-mix(in srgb,var(--pick-color) 28%,transparent); }
.gd-pick-cell.gd-in-ticket::after { content: '✓'; position: absolute; top: 3px; right: 5px; font-size: 10px; color: #fff; }
.gd-pick-cell:focus-visible { z-index: 2; outline: 2px solid #fff; outline-offset: 3px; }
.gd-pick-card .gd-card-footer { justify-content: center; margin-top: 4px; }
.gd-pick-card .gd-card-footer button { color: var(--muted); border: 0; background: transparent; font-size: 11px; }
.gd-pick-card .gd-card-footer button:hover { color: var(--mint); }
.gd-feature-grid { grid-template-columns: repeat(3,minmax(0,1fr)); }
@media (max-width:1100px) and (min-width:761px) { .gd-feature-card:first-child { grid-column: auto; } .gd-feature-grid { grid-template-columns: repeat(2,minmax(0,1fr)); } }
@media (max-width:380px) { .gd-pick-card, .gd-pick-card.gd-feature-card { padding-left: 12px; padding-right: 12px; } .gd-school h3 { font-size: 16px; } .gd-pick-value { gap: 4px; } .gd-pick-value b { font-size: 18px; } .gd-pick-value .teamlogo { width: 22px; height: 22px; } }
@media (max-width:380px) { .gameday #mainNavigation > button, .gameday #mainNavigation summary { padding-left: 8px; padding-right: 8px; font-size: 12px; } }

'use strict';
const Gameday=(()=>{
 const E=GamedayEngine,storeKey='darkhorse-tickets-v1',draftKey='darkhorse-betslip-v1';
 let slipTrigger=null,renderPool=null;
 const startedRequest=StartedGames.ready;
 let selectedDay=E.day(Date.now()),started=[],legs=[],saved=[],lensId=null,ready=false,storageOK=true,stake=10,showArchived=false,toastTimer;
 const signed=n=>n>0?'+'+n:String(n),money=n=>n==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
 const fullDay=k=>new Date(k+'T12:00Z').toLocaleDateString('en-US',{timeZone:'UTC',weekday:'long',month:'long',day:'numeric'});
 function allRows(){
  const map=new Map(started.map(g=>[g.id,{...g,archived:true}]));
  for(const f of M.forecasts){const g=game(f);if(!map.has(g.id)){
   const row={...g,f};
   if(Date.parse(g.date)<=Date.now()&&Date.parse(M.generatedAt)<Date.parse(g.date)&&Date.parse(M.inputRetrievedAt)<Date.parse(g.date)){
    const m=meta(g),quoteOK=Date.parse(m.retrievedAt)<Date.parse(g.date);
    row.savedPick={homeMargin:f.coreMargin,total:f.coreTotal,forecastAt:M.generatedAt,quote:quoteOK?{homeSpread:m.homeSpread,overUnder:m.overUnder}:null};
   }
   map.set(g.id,row);
  }}
  for(const live of LiveScores.games){const row=map.get(live.id);if(row&&row.home===live.home&&row.away===live.away&&live.state!=='pre')map.set(live.id,{...row,...live});}
  return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date));
 }
 function time(g){return g.timeValid===false?'Time TBA':new Date(g.date).toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'});}
 function status(g){if(g.state==='in')return g.detail||'In progress';return g.done?'Final':/POSTPONED|CANCEL/.test(g.status||'')?StartedGames.state(g):Date.parse(g.date)<=Date.now()?'Started · score pending':time(g)+' ET';}
